<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue';
import { api, ApiError, refreshCsrf, type Certificate } from './api';
type Screen = 'certificates' | 'credentials' | 'jobs' | 'settings';
const me = ref<any>(null), loading = ref(true), busy = ref(false), error = ref(''), notice = ref('');
const screen = ref<Screen>('certificates'), certificates = ref<Certificate[]>([]), credentials = ref<any[]>([]), jobs = ref<any[]>([]), tokens = ref<any[]>([]), users = ref<any[]>([]), system = ref<any>(null);
const username = ref('admin'), password = ref(''), newPassword = ref(''), search = ref(''), selected = ref<Certificate | null>(null);
type DirectoryField = 'outputDirectory' | 'webRoot';
const directoryError = ref<{ field: DirectoryField; message: string } | null>(null);
const outputInput = ref<HTMLInputElement | null>(null), webRootInput = ref<HTMLInputElement | null>(null);
const defaultOutput = computed<string | undefined>(() => system.value?.outputRoots?.[0]);
const outputLocked = ref(false);
function clearDirectoryError(field: DirectoryField) {
  if (directoryError.value?.field === field) directoryError.value = null;
}
const editor = ref(false), editingId = ref<string | null>(null), editingRevision = ref<number>(), domainText = ref('');
const credentialEditor = ref(false), credentialEdit = ref<any>(null), credential = ref({name:'', zoneId:'', zoneName:'', token:''});
const form = ref({name:'', domains:[] as string[], email:'', environment:'staging', validation:'dns', credentialId:'', webRoot:'', outputDirectory:'', fileName:'', format:'both', autoRenew:true, termsAccepted:false});
const oneTimeToken = ref(''), tokenName = ref(''), tokenDays = ref(30), tokenScopes = ref(['certificates:read', 'system:read']);
const newUser = ref({username:'',password:'',role:'Viewer'}), inspectDomain = ref('');
const canWrite = computed(() => me.value?.roles.some((r:string) => ['Administrator','Operator'].includes(r)));
const isAdmin = computed(() => me.value?.roles.includes('Administrator'));
const filtered = computed(() => certificates.value.filter(c => (c.name + c.domains.join(' ')).toLowerCase().includes(search.value.toLowerCase())));
const validCount = computed(() => certificates.value.filter(c => c.certificate.status === 'valid').length);
const failedCount = computed(() => certificates.value.filter(c => c.renewal.status === 'failed').length);
const activeCount = computed(() => certificates.value.filter(c => c.autoRenew).length);
const date = (s?:string|null) => s ? new Date(s).toLocaleString('zh-CN', { hour12:false }) : '—';
const statusName: Record<string,string> = { valid:'有效',expired:'已过期',notIssued:'待签发',paused:'已暂停',failed:'失败',scheduled:'已计划',queued:'排队中',running:'执行中',succeeded:'已完成' };
const days = (c:Certificate) => c.certificate.notAfterUtc ? Math.ceil((Date.parse(c.certificate.notAfterUtc)-Date.now())/86400000) : null;
async function run(action:()=>Promise<void>) { busy.value=true; error.value=''; notice.value=''; try { await action(); } catch(e) { error.value=(e as Error).message; if(e instanceof ApiError && e.status===401) me.value=null; } finally {busy.value=false;} }
async function load() {
  if (!me.value || me.value.mustChangePassword) return;
  certificates.value = (await api('/certificates?limit=100')).items;
  jobs.value = (await api('/jobs?limit=50')).items;
  system.value = await api('/system/status');
  if (canWrite.value) credentials.value=(await api('/credentials')).items;
  if (isAdmin.value && screen.value==='settings') {tokens.value=(await api('/api-tokens')).items;users.value=(await api('/users')).items;}
  if(selected.value) selected.value=certificates.value.find(c=>c.id===selected.value!.id)||null;
}
async function login() { await run(async()=> {await refreshCsrf(); await api('/auth/login','POST',{username:username.value,password:password.value}); await refreshCsrf(); me.value=await api('/auth/me'); if(!me.value.mustChangePassword) password.value=''; await load();}); }
async function changePassword() { await run(async()=>{await api('/auth/password','POST',{currentPassword:password.value,newPassword:newPassword.value}); password.value='';newPassword.value=''; await refreshCsrf();me.value=await api('/auth/me');await load();notice.value='密码已更新。';}); }
async function logout() {await run(async()=>{await api('/auth/logout','POST',{});me.value=null;selected.value=null;oneTimeToken.value='';password.value='';await refreshCsrf();});}
function edit(c?:Certificate) {
  error.value=''; directoryError.value=null; outputLocked.value=Boolean(c?.certificate.currentGeneration); editingId.value=c?.id||null; editingRevision.value=c?.revision;
  form.value=c ? {name:c.name,domains:[...c.domains],email:c.email,environment:c.environment,validation:c.validation,credentialId:c.credentialId||'',webRoot:c.webRoot||'',outputDirectory:c.outputDirectory,fileName:c.fileName,format:c.format,autoRenew:c.autoRenew,termsAccepted:c.termsAccepted}
    : {name:'',domains:[],email:'',environment:'staging',validation:'dns',credentialId:credentials.value[0]?.id||'',webRoot:system.value?.webRoots?.[0]||'',outputDirectory:system.value?.outputRoots?.[0]||'',fileName:'',format:'both',autoRenew:true,termsAccepted:false};
  domainText.value=form.value.domains.join('\n'); editor.value=true;
}
async function save() {await run(async()=>{
  directoryError.value = null;
  const body = {
    ...form.value,
    domains: domainText.value.split(/[\s,，;；]+/).filter(Boolean),
    credentialId: form.value.validation === 'dns' ? form.value.credentialId : null,
    outputDirectory: form.value.outputDirectory.trim(),
    webRoot: form.value.validation === 'http' ? form.value.webRoot.trim() : null,
  };
  let saved: Certificate;
  try {
    saved = await api<Certificate>(editingId.value ? `/certificates/${editingId.value}` : '/certificates', editingId.value ? 'PUT' : 'POST', body, editingRevision.value);
  } catch (e) {
    if (!(e instanceof ApiError)) throw e;
    const field = e.code === 'OUTPUT_DIRECTORY_INVALID' ? 'outputDirectory' : e.code === 'WEB_ROOT_INVALID' ? 'webRoot' : null;
    if (!field) throw e;
    directoryError.value = { field, message: e.message };
    await nextTick();
    const input = field === 'outputDirectory' ? outputInput : webRootInput;
    input.value?.focus();
    input.value?.scrollIntoView({ block: 'center' });
    return;
  }
  editor.value=false; await load(); selected.value=saved;notice.value='配置已保存，可在详情中发起签发。';
});}
async function job(c:Certificate,kind:string) {await run(async()=>{const response=await api(`/certificates/${c.id}/${kind}`,'POST',{domain:kind==='inspections'?inspectDomain.value||undefined:undefined});notice.value=`任务已加入队列 · ${response.jobId.slice(0,8)}`;await load();});}
async function toggle(c:Certificate) {await run(async()=>{await api(`/certificates/${c.id}`,'PUT',{...c,autoRenew:!c.autoRenew},c.revision);await load();notice.value=c.autoRenew?'自动续期已暂停。':'自动续期已恢复。';});}
const removeConfirm=ref(false);
async function remove(c:Certificate) {await run(async()=>{await api(`/certificates/${c.id}`,'DELETE',undefined,c.revision);selected.value=null;removeConfirm.value=false;await load();notice.value='已停止托管，服务器上的证书文件保留。';});}
function editCredential(c?:any){credentialEdit.value=c||null;credential.value={name:c?.name||'',zoneId:c?.zoneId||'',zoneName:c?.zoneName||'',token:''};credentialEditor.value=true;}
async function saveCredential(){await run(async()=>{const c=credentialEdit.value;await api(c?`/credentials/${c.id}`:'/credentials',c?'PUT':'POST',credential.value,c?.revision);credential.value.token='';credentialEditor.value=false;await load();notice.value='DNS 凭据已加密保存。';});}
async function createToken(){await run(async()=>{const r=await api('/api-tokens','POST',{name:tokenName.value,scopes:tokenScopes.value,days:tokenDays.value});oneTimeToken.value=r.token;tokenName.value='';await load();});}
async function revoke(id:string){await run(async()=>{await api('/api-tokens/'+id,'DELETE');await load();notice.value='Token 已立即撤销。';});}
async function createUser(){await run(async()=>{await api('/users','POST',newUser.value);newUser.value={username:'',password:'',role:'Viewer'};await load();notice.value='账号已创建，首次登录须修改密码。';});}
async function navigate(target:Screen){screen.value=target;selected.value=null;await run(load);}
let timer:ReturnType<typeof setInterval>;
onMounted(async()=>{try{await refreshCsrf();me.value=await api('/auth/me');await load();}catch(e){if(!(e instanceof ApiError&&e.status===401))error.value=(e as Error).message;}finally{loading.value=false;}timer=setInterval(()=>{if(me.value&&!me.value.mustChangePassword&&!document.hidden&&!busy.value&&!editor.value&&!credentialEditor.value)load().catch(()=>{});},15000);});
onUnmounted(()=>clearInterval(timer));
</script>

<template>
  <div v-if="loading" class="loading"><span class="brand-icon">C</span><p>正在连接 CertPilot…</p></div>
  <main v-else-if="!me || me.mustChangePassword" class="auth-layout">
    <section class="auth-story"><a class="brand" href="/"><span class="brand-icon">C</span>CertPilot<span class="version">v0.1</span></a><div><p class="eyebrow light">CERTIFICATES, ON AUTOPILOT</p><h1>让证书续期，<br>成为后台的日常。</h1><p>Windows 服务持续运行。从域名验证到证书输出，<br>在一个清晰的工作台中管理。</p><div class="auth-line"><span>01 / 安全连接</span><span>02 / 自动续期</span><span>03 / 持久任务</span></div></div><small>Self-hosted · Windows Server · ACME</small></section>
    <section class="auth-form"><div class="auth-card"><p class="eyebrow">YOUR CERTIFICATE WORKSPACE</p><h2>{{me?.mustChangePassword?'设置你的新密码':'欢迎回来'}}</h2><p class="muted">{{me?.mustChangePassword?'首次登录请修改临时密码，至少 14 位，包含大小写、数字和符号。':'登录本机 CertPilot 管理服务。'}}</p>
      <p v-if="error" role="alert" class="message error">{{error}}</p>
      <form v-if="!me" @submit.prevent="login"><label>用户名<input v-model="username" autocomplete="username" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required></label><button class="primary full" :disabled="busy">{{busy?'正在登录…':'登录工作台 →'}}</button></form>
      <form v-else @submit.prevent="changePassword"><label>当前临时密码<input v-model="password" type="password" autocomplete="current-password" required></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" minlength="14" required></label><button class="primary full" :disabled="busy">更新密码并进入 →</button></form>
      <div class="auth-help">首次使用？管理员凭据位于服务器数据目录的 <code>bootstrap-admin.txt</code>。修改密码后该文件自动删除。</div>
    </div></section>
  </main>
  <div v-else class="workspace">
    <aside class="sidebar"><a class="brand" href="/"><span class="brand-icon">C</span>CertPilot</a><div class="workspace-label">SERVER WORKSPACE <span>01</span></div><nav aria-label="主导航"><button :class="{active:screen==='certificates'}" @click="navigate('certificates')"><span>▧</span>证书管理<b>{{certificates.length}}</b></button><button v-if="canWrite" :class="{active:screen==='credentials'}" @click="navigate('credentials')"><span>⌘</span>DNS 凭据</button><button :class="{active:screen==='jobs'}" @click="navigate('jobs')"><span>☷</span>任务记录</button><button :class="{active:screen==='settings'}" @click="navigate('settings')"><span>⚙</span>服务与设置</button></nav><div class="sidebar-bottom"><div class="service-mini"><i :class="{warning:system?.service?.worker?.status!=='running'}"></i><div>后台服务<span>{{system?.service?.worker?.status==='running'?'自动续期调度中':'等待 Worker 心跳'}}</span></div></div><a href="/api-docs.html">Web API 文档 ↗</a><p>CertPilot · v0.1.0</p></div></aside>
    <div class="main"><header class="topbar"><span>工作空间 <span class="slash">/</span> {{({certificates:'证书管理',credentials:'DNS 凭据',jobs:'任务记录',settings:'服务与设置'})[screen]}}</span><div class="account"><span class="avatar">{{me.userName[0].toUpperCase()}}</span><span>{{me.userName}}<small>{{me.roles[0]}}</small></span><button class="text-button" @click="logout" :disabled="busy">退出</button></div></header>
      <div class="content"><div v-if="error" role="alert" class="message error"><span>{{error}}</span><button @click="error=''" aria-label="关闭错误">×</button></div><div v-if="notice" role="status" class="message success"><span>{{notice}}</span><button @click="notice=''" aria-label="关闭提示">×</button></div>
      <template v-if="screen==='certificates'&&!selected"><div class="page-heading"><div><p class="eyebrow">CERTIFICATE OVERVIEW</p><h1>证书管理<span class="count">{{certificates.length}}</span></h1><p class="muted">掌握每一张证书的状态，让安全连接持续在线。</p></div><button v-if="canWrite" class="primary" @click="edit()">＋ 新建证书</button></div><div class="stats"><article><span>托管证书</span><strong>{{certificates.length}}<small>张</small></strong><p>集中管理全部域名</p></article><article><span><i class="dot"></i>有效证书</span><strong>{{validCount}}<small>张</small></strong><p>以实际签发结果为准</p></article><article><span>自动续期</span><strong>{{activeCount}}<small>项</small></strong><p>Windows 服务后台调度</p></article><article :class="{attention:failedCount>0}"><span>需要关注</span><strong>{{failedCount}}<small>项</small></strong><p>续期失败与重试记录</p></article></div>
        <section class="panel"><div class="panel-toolbar"><div class="section-title">全部证书 <span>{{filtered.length}}</span></div><input class="search" v-model="search" placeholder="搜索名称或域名" aria-label="搜索证书"></div><div class="table-scroll"><table><thead><tr><th>证书 / 域名</th><th>当前状态</th><th>有效期</th><th>自动续期</th><th>环境</th><th></th></tr></thead><tbody><tr v-for="c in filtered" :key="c.id"><td><button class="cert-name" @click="selected=c;inspectDomain=c.domains.find(d=>!d.startsWith('*.'))||''">{{c.name}}</button><div class="domain mono">{{c.domains.join(' · ')}}</div></td><td><span class="badge" :class="c.certificate.status">{{statusName[c.certificate.status]}}</span><small v-if="c.renewal.error" class="danger">续期失败</small></td><td><span v-if="days(c)!==null">{{days(c)}} 天</span><span v-else class="muted">尚未签发</span><small>{{date(c.certificate.notAfterUtc)}}</small></td><td><span :class="{muted:!c.autoRenew}">{{c.autoRenew?'已开启':'已暂停'}}</span><small>{{date(c.renewal.nextAttemptAtUtc)}}</small></td><td><span class="environment" :class="c.environment">{{c.environment==='production'?'正式':'测试'}}</span></td><td><button class="text-button" @click="selected=c;inspectDomain=c.domains.find(d=>!d.startsWith('*.'))||''">查看 →</button></td></tr></tbody></table></div><div v-if="!filtered.length" class="empty"><span class="empty-icon">▧</span><h3>{{search?'没有匹配的证书':'从第一张证书开始'}}</h3><p>{{search?'试试其他名称或域名。':'添加域名与验证方式，保存后发起真实证书申请。'}}</p><button v-if="canWrite&&!search" class="secondary" @click="edit()">＋ 新建证书</button></div><footer class="panel-footer">显示 {{filtered.length}} / {{certificates.length}} 项 <span>每 15 秒更新 · 浏览器关闭后服务继续运行</span></footer></section><div class="info-note"><span>◇</span><p><b>签发与部署是两个步骤。</b> 证书输出成功后，需要将新版本部署到 IIS、Nginx 或其他服务。网站检测可确认实际使用的证书。</p></div>
      </template>
      <template v-if="screen==='certificates'&&selected"><button class="text-button back" @click="selected=null;removeConfirm=false">← 全部证书</button><div class="page-heading"><div><p class="eyebrow">CERTIFICATE DETAILS</p><h1>{{selected.name}}</h1><p class="mono muted">{{selected.domains.join(' · ')}}</p></div><button v-if="canWrite" class="secondary" @click="edit(selected)">编辑配置</button></div><div class="detail-grid"><section class="panel detail-panel"><div class="section-title">当前实际证书 <span class="badge" :class="selected.certificate.status">{{statusName[selected.certificate.status]}}</span></div><dl><dt>有效期</dt><dd>{{date(selected.certificate.notBeforeUtc)}} — {{date(selected.certificate.notAfterUtc)}}</dd><dt>实际签发域名</dt><dd class="mono">{{selected.certificate.domains.join(', ')||'尚未签发'}}</dd><dt>SHA-1 指纹</dt><dd class="mono wrap">{{selected.certificate.thumbprint||'—'}}</dd><dt>证书版本目录</dt><dd class="mono wrap">{{selected.certificate.currentGeneration||'—'}}</dd><dt>配置版本 / 已签发版本</dt><dd>{{selected.revision}} / {{selected.certificate.issuedRevision||'—'}}</dd></dl><p class="hint">更改配置不会立即改变已签发证书。PFX 密码仅可通过服务器本机工具获取。</p><div v-if="canWrite" class="actions"><button class="primary" :disabled="busy" @click="job(selected,'issuances')">申请证书</button><button class="secondary" :disabled="busy||!selected.certificate.notAfterUtc" @click="job(selected,'renewals')">立即续期</button></div></section><section class="panel detail-panel"><div class="section-title">续期与输出</div><dl><dt>自动续期</dt><dd>{{selected.autoRenew?'已开启':'已暂停'}}</dd><dt>下次计划</dt><dd>{{date(selected.renewal.nextAttemptAtUtc)}}</dd><dt>验证方式</dt><dd>{{selected.validation==='dns'?'DNS-01 / Cloudflare':'HTTP-01 / Webroot'}}</dd><dt>输出格式</dt><dd>{{selected.format.toUpperCase()}}</dd><dt>输出目录</dt><dd class="mono wrap">{{selected.outputDirectory}}</dd><dt>基础文件名</dt><dd class="mono">{{selected.fileName}}</dd></dl><p v-if="selected.renewal.error" class="message error">{{selected.renewal.error}}</p><button v-if="canWrite" class="secondary" :disabled="busy" @click="toggle(selected)">{{selected.autoRenew?'暂停自动续期':'恢复自动续期'}}</button></section></div><section class="panel detail-panel"><div class="section-title">网站 TLS 检测</div><p class="muted">从服务器检测所选域名的公网 443 端口，校验信任链、域名与托管证书指纹。检测不会部署证书。</p><div v-if="canWrite" class="inline-form"><label>检测域名<select v-model="inspectDomain"><option v-for="d in selected.domains.filter(d=>!d.startsWith('*.'))" :key="d">{{d}}</option></select></label><button class="secondary" :disabled="busy||!inspectDomain" @click="job(selected,'inspections')">发起检测</button></div></section><section class="panel detail-panel"><div class="section-title">最近任务</div><div v-for="j in jobs.filter(j=>j.certificateId===selected!.id)" :key="j.id" class="job-line"><div><b>{{({issuance:'证书申请',renewal:'自动续期',inspection:'网站检测'} as any)[j.kind]}}</b><small>{{date(j.createdAtUtc)}} · {{j.stage}}</small><p v-if="j.error" class="danger">{{j.error}}</p><pre v-if="j.result">{{JSON.stringify(j.result,null,2)}}</pre></div><span class="badge" :class="j.status">{{statusName[j.status]}}</span></div><p v-if="!jobs.some(j=>j.certificateId===selected!.id)" class="muted">暂无任务。签发后可在这里查看各阶段与结果。</p></section><div v-if="canWrite" class="remove-block"><button v-if="!removeConfirm" class="text-button danger" @click="removeConfirm=true">停止托管此证书</button><template v-else><p>确认停止托管？现有文件保留，自动续期将停止。</p><button class="danger-button" :disabled="busy" @click="remove(selected)">确认停止托管</button><button class="secondary" @click="removeConfirm=false">取消</button></template></div></template>
      <template v-if="screen==='credentials'"><div class="page-heading"><div><p class="eyebrow">DNS CONNECTIONS</p><h1>DNS 凭据</h1><p class="muted">授权服务自动完成 DNS-01 验证，支持通配符证书。</p></div><button class="primary" @click="editCredential()">＋ 添加凭据</button></div><div class="credential-grid"><article v-for="c in credentials" :key="c.id" class="panel credential-card"><div class="provider-mark">CF</div><span class="environment">Cloudflare</span><h3>{{c.name}}</h3><p class="mono">{{c.zoneName}}</p><p class="muted mono wrap">Zone {{c.zoneId}}</p><div class="credential-footer"><span>密钥已加密 · v{{c.revision}}</span><button class="text-button" @click="editCredential(c)">替换 Token →</button></div></article></div><div v-if="!credentials.length" class="panel empty"><span class="empty-icon">⌘</span><h3>连接你的 DNS 服务</h3><p>添加指定 Cloudflare Zone 的 API Token，权限为 Zone DNS Edit。</p><button class="secondary" @click="editCredential()">＋ 添加凭据</button></div><div class="info-note"><span>◇</span><p>当前版本支持 Cloudflare。密钥保存在服务器加密存储中，API 不返回原文。域名需属于所选 Zone，暂不支持 CNAME 委派验证。</p></div></template>
      <template v-if="screen==='jobs'"><div class="page-heading"><div><p class="eyebrow">ACTIVITY & EXECUTION</p><h1>任务记录</h1><p class="muted">签发、续期与网站检测的持久化执行记录，最近 50 项。</p></div><button class="secondary" @click="run(load)" :disabled="busy">刷新记录</button></div><section class="panel"><div v-for="j in jobs" :key="j.id" class="job-line"><div><b>{{certificates.find(c=>c.id===j.certificateId)?.name||'已移除配置'}} · {{({issuance:'证书申请',renewal:'续期',inspection:'网站检测'} as any)[j.kind]}}</b><small>{{date(j.createdAtUtc)}} · {{j.stage}} · 第 {{j.attempt}} 次执行</small><p v-if="j.error" class="danger">{{j.error}}</p><details v-if="j.result"><summary>查看结果</summary><pre>{{JSON.stringify(j.result,null,2)}}</pre></details></div><span class="badge" :class="j.status">{{statusName[j.status]}}</span></div><div v-if="!jobs.length" class="empty"><span class="empty-icon">☷</span><h3>运行轨迹，从这里开始</h3><p>创建证书配置后发起申请，任务将持久保存于服务器。</p></div></section></template>
      <template v-if="screen==='settings'"><div class="page-heading"><div><p class="eyebrow">SYSTEM & ACCESS</p><h1>服务与设置</h1><p class="muted">查看运行状态，管理集成访问与人员权限。</p></div><a class="secondary" href="/api-docs.html">查看 API 文档 ↗</a></div><section class="panel detail-panel"><div class="section-title">服务状态</div><dl><dt>版本 / 平台</dt><dd>{{system?.service?.version}} / {{system?.service?.platform}}</dd><dt>Web / Worker</dt><dd>{{system?.service?.web?.status}} / {{system?.service?.worker?.status}}</dd><dt>Worker 心跳</dt><dd>{{date(system?.service?.worker?.heartbeatUtc)}}</dd><dt>运行中 / 排队</dt><dd>{{system?.running}} / {{system?.queued}}</dd><dt>允许输出根目录</dt><dd class="mono wrap">{{system?.outputRoots?.join('\n')}}</dd><dt>允许 HTTP Webroot</dt><dd class="mono wrap">{{system?.webRoots?.join('\n')||'未配置'}}</dd></dl><p class="hint">监听地址、TLS 和目录授权在服务器 appsettings.Local.json 配置；修改后重启服务。</p></section><template v-if="isAdmin"><section class="panel detail-panel"><div class="section-title">API 服务 Token</div><p class="muted">供后端集成使用。仅创建时显示原文，按范围授权，随时撤销。</p><div v-if="oneTimeToken" class="message success token-result"><b>请立即保存，此值仅显示一次</b><code>{{oneTimeToken}}</code><button @click="oneTimeToken=''">已保存，关闭</button></div><form @submit.prevent="createToken"><div class="form-row"><label>名称<input v-model="tokenName" required maxlength="80" placeholder="例如：监控后端"></label><label>有效天数<input v-model.number="tokenDays" type="number" min="1" max="365" required></label></div><div class="scope-list"><label v-for="scope in ['certificates:read','certificates:write','jobs:execute','credentials:write','system:read']" :key="scope" class="checkbox"><input type="checkbox" v-model="tokenScopes" :value="scope">{{scope}}</label></div><button class="secondary" :disabled="busy">创建 Token</button></form><div v-for="t in tokens" :key="t.id" class="job-line"><div><b>{{t.name}}</b><small>{{t.scopes}} · 到期 {{date(t.expiresAtUtc)}}</small></div><span v-if="t.revoked" class="muted">已撤销</span><button v-else class="text-button danger" @click="revoke(t.id)" :disabled="busy">撤销</button></div></section><section class="panel detail-panel"><div class="section-title">本地人员账号</div><p class="muted">Viewer 查看状态，Operator 管理证书，Administrator 管理全部资源。</p><form @submit.prevent="createUser"><div class="form-row"><label>用户名<input v-model="newUser.username" required autocomplete="off"></label><label>临时密码<input v-model="newUser.password" type="password" minlength="14" required autocomplete="new-password"></label><label>角色<select v-model="newUser.role"><option>Viewer</option><option>Operator</option><option>Administrator</option></select></label></div><button class="secondary" :disabled="busy">创建账号</button></form><div class="user-chips"><span v-for="u in users" :key="u.id">{{u.userName}} <small v-if="u.mustChangePassword">待改密码</small></span></div></section></template></template>
      <footer class="app-footer"><span>CertPilot · 让安全连接持续在线</span><span>自托管证书自动化 / v0.1.0</span></footer></div>
    </div>
  </div>
  <div v-if="editor" class="modal-backdrop" @click.self="editor=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="editor-title"><header><div><p class="eyebrow">CERTIFICATE CONFIGURATION</p><h2 id="editor-title">{{editingId?'编辑证书':'新建证书'}}</h2></div><button class="close" aria-label="关闭" @click="editor=false">×</button></header><form @submit.prevent="save"><div class="modal-body"><p v-if="error" class="message error" role="alert">{{error}}</p><div class="form-row"><label>证书名称 *<input v-model="form.name" required maxlength="80" placeholder="例如：官方网站"></label><label>联系邮箱 *<input v-model="form.email" type="email" required placeholder="admin@example.com"></label></div><label>域名 *<textarea v-model="domainText" rows="3" required placeholder="example.com&#10;*.example.com"></textarea><small>每行一个域名。通配符必须选择 DNS-01。</small></label><div class="form-row"><label>CA 环境<select v-model="form.environment"><option value="staging">测试 / Staging（不受浏览器信任）</option><option value="production">正式 / Production</option></select></label><label>验证方式<select v-model="form.validation" @change="clearDirectoryError('webRoot')"><option value="dns">DNS-01 / Cloudflare</option><option value="http">HTTP-01 / Webroot</option></select></label></div><label v-if="form.validation==='dns'">DNS 凭据 *<select v-model="form.credentialId" required><option disabled value="">请先在 DNS 凭据页添加授权</option><option v-for="c in credentials" :key="c.id" :value="c.id">{{c.name}} · {{c.zoneName}}</option></select></label><div v-else class="directory-group">
  <label>HTTP-01 网站根目录 *<input ref="webRootInput" v-model="form.webRoot" required placeholder="服务器实际网站根目录" aria-describedby="webroot-hint webroot-error" :aria-invalid="directoryError?.field === 'webRoot'" @input="clearDirectoryError('webRoot')">
    <small id="webroot-hint">{{ system?.webRoots?.length ? '允许的网站根目录：' + system.webRoots.join('；') : '服务尚未登记网站根目录。请管理员将实际站点目录加入服务配置的 WebRoots。' }}</small>
  </label>
  <p v-if="directoryError?.field === 'webRoot'" id="webroot-error" class="directory-error" role="alert">{{ directoryError.message }}</p>
</div>
<div class="form-divider">证书输出 <span>路径属于服务器</span></div>
<div class="directory-group">
  <label>证书保存目录 *<input ref="outputInput" v-model="form.outputDirectory" required :readonly="outputLocked" placeholder="服务器本地绝对目录" aria-describedby="output-hint output-error" :aria-invalid="directoryError?.field === 'outputDirectory'" @input="clearDirectoryError('outputDirectory')">
    <small id="output-hint">允许的输出根目录：{{ system?.outputRoots?.join('；') }}</small>
  </label>
  <p v-if="directoryError?.field === 'outputDirectory'" id="output-error" class="directory-error" role="alert">{{ directoryError.message }}</p>
  <button v-if="defaultOutput && !outputLocked" type="button" class="secondary" @click="form.outputDirectory = defaultOutput; clearDirectoryError('outputDirectory')">使用默认保存目录</button>
</div>
<div class="form-row"><label>基础文件名 *<input v-model="form.fileName" required placeholder="example-com" maxlength="64"></label><label>输出格式<select v-model="form.format"><option value="both">PEM + PFX</option><option value="pem">PEM</option><option value="pfx">PFX</option></select></label></div><label class="checkbox"><input v-model="form.autoRenew" type="checkbox">开启自动续期</label><label class="checkbox"><input v-model="form.termsAccepted" type="checkbox">我已阅读并接受 <a href="https://letsencrypt.org/repository/" target="_blank" rel="noreferrer">Let's Encrypt 订阅协议 ↗</a></label><p v-if="form.environment==='production'" class="hint">正式签发受 CA 频率限制。建议先在测试环境验证域名与目录配置。</p></div><footer><button type="button" class="secondary" @click="editor=false">取消</button><button class="primary" :disabled="busy">{{busy?'保存中…':'保存配置'}}</button></footer></form></section></div>
  <div v-if="credentialEditor" class="modal-backdrop" @click.self="credentialEditor=false"><section class="modal compact" role="dialog" aria-modal="true" aria-labelledby="credential-title"><header><div><p class="eyebrow">CLOUDFLARE DNS</p><h2 id="credential-title">{{credentialEdit?'替换 DNS Token':'添加 DNS 凭据'}}</h2></div><button class="close" aria-label="关闭" @click="credentialEditor=false">×</button></header><form @submit.prevent="saveCredential"><div class="modal-body"><p v-if="error" class="message error" role="alert">{{error}}</p><label>凭据名称 *<input v-model="credential.name" required maxlength="80"></label><label>Zone 域名 *<input v-model="credential.zoneName" required :readonly="!!credentialEdit" placeholder="example.com"></label><label>Zone ID *<input v-model="credential.zoneId" required :readonly="!!credentialEdit" pattern="[a-fA-F0-9]{32}"></label><label>API Token *<input v-model="credential.token" type="password" required autocomplete="off"><small>限制为该 Zone 的 DNS Edit 权限。</small></label><p class="hint">当前仅支持 Cloudflare 直接托管的 Zone。Token 加密保存在服务器，保存后无法回读。</p></div><footer><button type="button" class="secondary" @click="credentialEditor=false">取消</button><button class="primary" :disabled="busy">保存凭据</button></footer></form></section></div>
</template>
